package io.eucl.pvparenapoints;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;

@ConfigGroup("pvparenapointstracker")
public interface PvpArenaPointsConfig extends Config {}

package io.eucl.pvparenapoints;

import com.google.inject.Provides;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.WorldType;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.infobox.Counter;
import net.runelite.client.ui.overlay.infobox.InfoBoxManager;

import javax.inject.Inject;
import java.awt.image.BufferedImage;
import java.util.Optional;

@Slf4j
@PluginDescriptor(
	name = "PvP Arena Reward Points Tracker"
)
public class PvpArenaPointsPlugin extends Plugin

{

	private static final int EMIRS_ARENA_REGION = 13362;

	private static final int EMIRS_ARENA_NORTH_REGION = 13363;

	@Inject
	private Client client;

	@Inject
	private PvpArenaPointsConfig config;

	@Inject
	private ItemManager itemManager;

	@Inject
	private InfoBoxManager infoBoxManager;

	private Counter counter;

	@Getter
	private int points = -1;

	@Override
	protected void startUp() throws Exception
	{
		if (client.getGameState() == GameState.LOGGED_IN) {
			this.points = client.getVarbitValue(VarbitID.PVPA_POINTS_CURRENCY);
			log.info("initial points: {}", this.points);
			processInfoBox();
		}
	}

	private boolean isCounterActive() {
		boolean isOnPvpArenaWorld = client.getWorldType().contains(WorldType.PVP_ARENA);

		int playerRegion = Optional.ofNullable(client.getLocalPlayer())
				.map(p -> p.getWorldLocation().getRegionID())
				.orElse(-1);
		boolean inEmirsArena = playerRegion == EMIRS_ARENA_REGION || playerRegion == EMIRS_ARENA_NORTH_REGION;

		return isOnPvpArenaWorld || inEmirsArena;
	}

	@Subscribe
	public void onGameTick(GameTick tick) {
		processInfoBox();
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event) {
		if (event.getVarbitId() == VarbitID.PVPA_POINTS_CURRENCY) {
			this.points = event.getValue();
			log.info("points updated: {}", this.points);
			processInfoBox();
			this.counter.setCount(this.points);
		}
	}

    @Provides
	PvpArenaPointsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(PvpArenaPointsConfig.class);
	}

	private void processInfoBox() {
		if (client.getGameState() == GameState.LOGGED_IN && isCounterActive()) {
			if (this.counter == null) {
				BufferedImage image = this.itemManager.getImage(ItemID.PVPA_IMBUING_SCROLL);
				this.counter = new Counter(image, this, this.points);
				this.counter.setTooltip("PvP Arena Reward Points");
				this.infoBoxManager.addInfoBox(this.counter);
			}
		} else {
			if (this.counter != null) {
				infoBoxManager.removeInfoBox(this.counter);
				this.counter = null;
			}
		}
	}
}

package io.eucl.pvparenapoints;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class PvpArenaPointsPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(PvpArenaPointsPlugin.class);
		RuneLite.main(args);
	}
}
